using System.Runtime.InteropServices;
using System.Text.Json;
class DeviceService {
 record AccessPoint(string id,string name,int signal,int security,bool saved,bool connected);
 class Bt {public string address="",name="",kind="";public bool paired,connected;public int major;}
 readonly Dictionary<string,(IntPtr handle,AccessPoint info)> accessPoints=new();
 readonly Dictionary<string,Bt> devices=new(StringComparer.OrdinalIgnoreCase);
 readonly bool writable;IntPtr wifi;int wifiInit,btInit;bool wifiScanning,btScanning;string message="",pendingBluetooth="";DateTime lastBluetoothAttempt;
 readonly Native.Done scanFinished,connectFinished;readonly Native.Discovery discovery;readonly Native.Bond bonded;readonly Native.Connection hidChanged;readonly Native.DeviceConnection deviceChanged;
 public DeviceService(bool allowWrites){writable=allowWrites;
  wifiInit=Native.wifi_manager_initialize(out wifi);btInit=Native.bt_initialize();
  scanFinished=(r,_)=>{wifiScanning=false;if(r==0)LoadAccessPoints();else message="Wi-Fi scan failed ("+r+")";};
  connectFinished=(r,_)=>{message=r==0?"Wi-Fi connection completed":"Wi-Fi connection failed ("+r+")";};
  discovery=(r,state,p,_)=>{if(r!=0){btScanning=false;message="Bluetooth scan failed ("+r+")";return;}btScanning=state!=1;if(state==2&&p!=IntPtr.Zero){var d=Marshal.PtrToStructure<Native.Found>(p);AddDevice(Native.Text(d.address),Native.Text(d.name),d.kind.major,d.paired,false);}};
  bonded=(r,p,_)=>{if(p==IntPtr.Zero)return;var d=Marshal.PtrToStructure<Native.Device>(p);var address=Native.Text(d.address);AddDevice(address,Native.Text(d.name),d.kind.major,d.paired,d.connected);if(address==pendingBluetooth){if(r==0)ConnectProfile(address);else{message="Pairing failed ("+r+")";pendingBluetooth="";}}};
  hidChanged=(r,connected,p,_)=>{var a=Native.Text(p);if(devices.TryGetValue(a,out var d))d.connected=connected;if(a==pendingBluetooth){message=r==0&&connected?"Bluetooth connected":"Bluetooth connection failed ("+r+")";pendingBluetooth="";}};
  deviceChanged=(connected,p,_)=>{if(p==IntPtr.Zero)return;var a=Native.Text(Marshal.ReadIntPtr(p));if(devices.TryGetValue(a,out var d))d.connected=connected;if(connected&&a==pendingBluetooth){message="Bluetooth connected";pendingBluetooth="";}};
  if(btInit==0&&writable){Native.bt_adapter_set_device_discovery_state_changed_cb(discovery,IntPtr.Zero);Native.bt_device_set_bond_created_cb(bonded,IntPtr.Zero);Native.bt_device_set_connection_state_changed_cb(deviceChanged,IntPtr.Zero);Native.bt_audio_initialize();Native.bt_hid_host_initialize(hidChanged,IntPtr.Zero);}
 }
 static void Check(int code,string action){if(code!=0)throw new InvalidOperationException(action+" failed ("+code+")");}
 static string String(JsonElement json,string key)=>json.TryGetProperty(key,out var p)&&p.ValueKind==JsonValueKind.String?p.GetString()??"":"";
 void AddDevice(string address,string name,int major,bool paired,bool connected){if(string.IsNullOrWhiteSpace(address))return;if(!devices.TryGetValue(address,out var d)){d=new Bt{address=address};devices[address]=d;}if(!string.IsNullOrWhiteSpace(name))d.name=name;d.major=major;d.kind=major==4?"audio":major==5?"input":"other";d.paired=paired;d.connected=connected;}
 void ReadBonded(){if(btInit!=0)return;Native.Each callback=(p,_)=>{var d=Marshal.PtrToStructure<Native.Device>(p);AddDevice(Native.Text(d.address),Native.Text(d.name),d.kind.major,d.paired,d.connected);return true;};Native.bt_adapter_foreach_bonded_device(callback,IntPtr.Zero);GC.KeepAlive(callback);}
 AccessPoint ReadAP(IntPtr ap,string id){Check(Native.wifi_manager_ap_get_essid(ap,out var p),"Read network name");string name=Native.Text(p);Native.free(p);Native.wifi_manager_ap_get_rssi(ap,out var rssi);Native.wifi_manager_ap_get_security_type(ap,out var security);Native.wifi_manager_ap_is_favorite(ap,out var saved);Native.wifi_manager_ap_get_connection_state(ap,out var state);return new(id,name,rssi,security,saved,state>=3);}
 void LoadAccessPoints(){foreach(var pair in accessPoints.Values)Native.wifi_manager_ap_destroy(pair.handle);accessPoints.Clear();Native.Each callback=(ap,_)=>{if(Native.wifi_manager_ap_clone(out var clone,ap)==0){var id=Guid.NewGuid().ToString("N");try{var info=ReadAP(clone,id);accessPoints[id]=(clone,info);}catch{Native.wifi_manager_ap_destroy(clone);}}return true;};Check(Native.wifi_manager_foreach_found_ap(wifi,callback,IntPtr.Zero),"Read networks");GC.KeepAlive(callback);}
 record Brightness(bool available,bool enabled,int? value,int min,int max,int step);
 Brightness ReadBrightness(){bool read=Native.CSharpGetItemValue("brightness",out _,out var raw);bool range=Native.settings_get_item_minmax_step("brightness",out var low,out var high,out var increment);bool enableRead=Native.CSharpGetItemEnable("brightness",out var enabled);bool valid=range&&double.IsFinite(low)&&double.IsFinite(high)&&double.IsFinite(increment)&&low>=0&&high>low&&high<=1000&&increment>=1&&low==Math.Truncate(low)&&high==Math.Truncate(high)&&increment==Math.Truncate(increment);int? value=read&&int.TryParse(Native.Text(raw),out var parsed)&&valid&&parsed>=low&&parsed<=high?parsed:null;return new Brightness(value.HasValue,enableRead&&enabled,value,valid?(int)low:0,valid?(int)high:0,valid?(int)increment:1);}
 object State(){
  int wifiState=-1;string ssid="";if(wifiInit==0){Native.wifi_manager_get_connection_state(wifi,out wifiState);if(Native.wifi_manager_get_connected_ap(wifi,out var connected)==0){try{ssid=ReadAP(connected,"").name;}finally{Native.wifi_manager_ap_destroy(connected);}}}
  bool sleepOk=Native.CSharpGetItemValue("sleeptimer",out _,out var sleepValue);var sleepIndex=sleepOk&&int.TryParse(Native.Text(sleepValue),out var idx)?idx:-1;int[] minutes={0,30,60,120,180};int? sleepMinutes=sleepIndex>=0&&sleepIndex<minutes.Length?minutes[sleepIndex]:null;
  ReadBonded();if(pendingBluetooth!=""&&DateTime.UtcNow-lastBluetoothAttempt>TimeSpan.FromSeconds(45)){message="Bluetooth connection timed out";pendingBluetooth="";}
  return new{ready=true,writeEnabled=writable,brightness=ReadBrightness(),wifi=new{available=wifiInit==0,connected=wifiState>=3,ssid,scanning=wifiScanning,networks=accessPoints.Values.Select(x=>x.info).OrderByDescending(x=>x.signal).ToArray()},bluetooth=new{available=btInit==0,scanning=btScanning,pending=pendingBluetooth,devices=devices.Values.Where(x=>!string.IsNullOrWhiteSpace(x.name)).Select(x=>new{x.address,x.name,x.kind,x.paired,x.connected}).ToArray()},sleep=new{available=sleepOk,minutes=sleepMinutes,options=minutes},message};
 }
 void ConnectProfile(string address){if(!devices.TryGetValue(address,out var device))throw new InvalidOperationException("Device no longer available");int result=device.kind=="audio"?Native.bt_audio_connect(address,2):device.kind=="input"?Native.bt_hid_host_connect(address):-95;if(result!=0){pendingBluetooth="";message="Bluetooth connection failed ("+result+")";}else message="Connecting to "+device.name;}
 public object Handle(string route,JsonElement data){if(route=="state")return State();if(!writable)throw new InvalidOperationException("Device changes are disabled in read-only diagnostic mode");
  switch(route){
   case "wifi/scan":if(!wifiScanning){Check(wifiInit,"Initialize Wi-Fi");wifiScanning=true;var r=Native.wifi_manager_scan(wifi,scanFinished,IntPtr.Zero);if(r!=0){wifiScanning=false;Check(r,"Scan Wi-Fi");}}break;
   case "wifi/connect":{var id=String(data,"id");if(!accessPoints.TryGetValue(id,out var selected))throw new InvalidOperationException("Network list changed; scan again");if(wifiScanning)throw new InvalidOperationException("Wait for scan to finish");var pass=String(data,"password");if(pass.Length>256)throw new InvalidOperationException("Password too long");if(selected.info.security!=0&&!selected.info.saved){if(pass.Length==0)throw new InvalidOperationException("Enter the network password");Check(Native.wifi_manager_ap_set_passphrase(selected.handle,pass),"Set Wi-Fi password");}Check(Native.wifi_manager_connect(wifi,selected.handle,connectFinished,IntPtr.Zero),"Connect Wi-Fi");message="Connecting to "+selected.info.name;break;}
   case "bluetooth/scan":Check(btInit,"Initialize Bluetooth");if(!btScanning){Check(Native.bt_adapter_start_device_discovery(),"Scan Bluetooth");btScanning=true;}break;
   case "bluetooth/connect":{var address=String(data,"address");if(!devices.TryGetValue(address,out var d))throw new InvalidOperationException("Device not found; scan again");if(d.kind=="other")throw new InvalidOperationException("This device does not advertise an audio or input profile");if(d.connected)break;pendingBluetooth=address;lastBluetoothAttempt=DateTime.UtcNow;if(btScanning){Native.bt_adapter_stop_device_discovery();btScanning=false;}if(d.paired)ConnectProfile(address);else{var code=Native.bt_device_create_bond(address);if(code!=0){pendingBluetooth="";Check(code,"Pair Bluetooth");}message="Pairing with "+d.name;}break;}
   case "brightness/set":{var current=ReadBrightness();if(!current.available||!current.enabled)throw new InvalidOperationException("Brightness cannot be adjusted in the current picture mode");if(!data.TryGetProperty("value",out var b)||!b.TryGetInt32(out var value)||value<current.min||value>current.max||(value-current.min)%current.step!=0)throw new InvalidOperationException("Choose a supported brightness value");if(!Native.CSharpSetItemValue("brightness",value.ToString()))throw new InvalidOperationException("Monitor rejected the brightness setting");var actual=ReadBrightness();if(!actual.available||actual.value!=value)throw new InvalidOperationException("Brightness change could not be verified");message="";break;}
   case "sleep/set":{if(!data.TryGetProperty("minutes",out var m)||!m.TryGetInt32(out var value))throw new InvalidOperationException("Choose a timer duration");int[] allowed={0,30,60,120,180};int index=Array.IndexOf(allowed,value);if(index<0)throw new InvalidOperationException("Unsupported timer duration");if(!Native.CSharpSetItemValue("sleeptimer",index.ToString()))throw new InvalidOperationException("Monitor rejected the timer setting");if(!Native.CSharpGetItemValue("sleeptimer",out _,out var actual)||Native.Text(actual)!=index.ToString())throw new InvalidOperationException("Timer change could not be verified");message=value==0?"Sleep Timer is off":"Sleep Timer set to "+value+" minutes";break;}
   default:throw new InvalidOperationException("Unknown device action");
  }
  return State();
 }
}
